    /**
     * Finds a built-in type by identifier.
     *
     * @param id the identifier
     * @return the matching type, if present
     */
    public static Optional<SoundType> get(Identifier id) {
        return TYPES.get(id);
    }

    /**
     * Returns the built-in types in declaration order.
     *
     * @return an unmodifiable list of built-in types
     */
    public static List<SoundType> values() {
        return TYPES.values();
    }

    private static SoundType type(String id) {
        return TYPES.register(SoundType.of(Identifier.parse(id)));
    }
